def daily_topics(count=5, day_number=None):
    from datetime import datetime
    day_number = day_number if day_number is not None else datetime.now().timetuple().tm_yday
    start = ((day_number - 1) * count) % len(TOPICS)
    return [TOPICS[(start + i) % len(TOPICS)] for i in range(min(count, len(TOPICS)))]
